/**
 * Decision-model cascade verifier (TL3): page image + the cheap target's output -> P(extraction failed).
 *
 * Implements the `CascadeVerifier` seam. Two image decision models (clef-omni and clef-flash) answer the same
 * generic dimension questions (text present, numbers, reading order, table rows/columns/cells, formulas, a quality
 * score); a logistic head fitted offline (verifier-config.ts, generated by scripts/page-router/tune_verifier.py)
 * combines the answers with target class and output size, then Platt scaling turns the score into P(fail).
 *
 * Gating (expected value, see `escalationThreshold`): escalating a page that really failed gains `gainGivenFail`
 * quality for `escalationUsdPerPage`; with V = USD the operator pays per unit of page quality, escalate iff
 * pFail >= escalationUsdPerPage / (gainGivenFail * V). The verifier itself is only worth running when V is at least
 * `minValueUsdPerQualityUnit`; below that the free checks capture the gain and the call is skipped (no cost).
 *
 * Health: every member is canary-checked through the shared health registry and its answers are screened for
 * degeneracy. A member that is unhealthy, unavailable or degenerate makes the verifier abstain (`null`), so the
 * stage falls back to the free checks alone; a generative LLM is never substituted.
 */

import { readFile } from "node:fs/promises";

import { findDecisionModel, type DecisionModel } from "@docslurp/shared";
import sharp from "sharp";

import type { PipelineUsageEventLedger } from "../pipeline/usage-ledger.js";
import type { CascadeVerifier, VerifierRequest, VerifierVerdict } from "./cascade.js";
import {
  DecisionRequestError,
  DecisionUnavailableError,
  PAGE_ROUTE_DECISION_CANARY_METRIC,
  createDecisionClient,
  imageDataUrlPart,
  recordDecisionUsage,
  type DecisionAnswer,
  type DecisionCallResult,
  type DecisionClient,
  type DecisionQuestion,
} from "./decision-client.js";
import {
  DecisionDegenerateError,
  DecisionModelUnhealthyError,
  answerSignals,
  decisionModelHealth,
  detectDegenerate,
  runCanary,
  type DecisionModelHealthRegistry,
} from "./health/index.js";
import { PAGE_VERIFIER_FITTED } from "./verifier-config.js";

export const VERIFIER_QUESTIONS = PAGE_VERIFIER_FITTED.questions as unknown as Record<string, DecisionQuestion>;
export const VERIFIER_FORMAT = "raw/dims2/768px";
/**
 * Longest page edge sent to the decision models: 768 px, the resolution the fitted head (verifier-config.ts, TL3)
 * was tuned and thresholded at for both clef-omni and clef-flash. E3 found the image adds little beyond wrong-page
 * detection and a clef-flash-only head was no worse at 384 px (dev+cal answers-only AUROC 0.789 vs 0.771 at 768),
 * but clef-omni was never run at 384 px, so serving 384 px would feed the head inputs it was not fit on. Lower it
 * only together with a head refit on 384 px answers of both models.
 */
export const VERIFIER_IMAGE_LONG_EDGE = 768;
/** The tuned head saw candidate text cut to this many characters. */
export const VERIFIER_MAX_CANDIDATE_CHARS = 6000;

const CANDIDATE_LABEL = "Candidate transcription:\n";

// ---- Fitted head ------------------------------------------------------------

export type VerifierSlot = "omni" | "flash";

export interface VerifierFeatureInput {
  targetId: string;
  text: string;
  answers: Record<VerifierSlot, Record<string, DecisionAnswer>>;
}

/** Same classes as the offline fit: native text layer, OCR, private parser, hosted/other VLM. */
export function targetClass(targetId: string): "native" | "ocr" | "parser" | "vlm" {
  if (targetId.startsWith("native")) return "native";
  if (targetId.startsWith("ocr")) return "ocr";
  if (targetId.startsWith("vlm:private")) return "parser";
  return "vlm";
}

function logit(p: number): number {
  const c = Math.min(Math.max(p, 0.02), 0.98);
  return Math.log(c / (1 - c)) / 4;
}

function answerFeatures(slot: VerifierSlot, answers: Record<string, DecisionAnswer>, out: Map<string, number>): void {
  for (const [question, answer] of Object.entries(answers)) {
    if (answer.type === "noul") {
      out.set(`${slot}:${question}`, logit(answer.noul));
    } else if (answer.type === "score") {
      const levels = Object.keys(answer.probabilities).map(Number).sort((a, b) => a - b);
      const total = Object.values(answer.probabilities).reduce((a, b) => a + b, 0) || 1;
      const max = Math.max(levels[levels.length - 1] ?? 1, 1);
      let expected = 0;
      let low = 0;
      for (const [key, p] of Object.entries(answer.probabilities)) {
        expected += Number(key) * p;
        if (Number(key) <= 1) low += p;
      }
      out.set(`${slot}:${question}`, expected / total / max);
      out.set(`${slot}:${question}_lo`, low / total);
    }
  }
}

/**
 * Feature vector in the fitted order. The verifier is only consulted after every free check passed, so the
 * `free`, `free2` and `ragged` flags are 0 by construction.
 */
export function verifierFeatures(input: VerifierFeatureInput): number[] {
  const values = new Map<string, number>();
  answerFeatures("omni", input.answers.omni, values);
  answerFeatures("flash", input.answers.flash, values);
  const cls = targetClass(input.targetId);
  for (const c of ["native", "ocr", "parser", "vlm"] as const) values.set(`cls_${c}`, cls === c ? 1 : 0);
  values.set("len", Math.log1p(input.text.length) / 8);
  values.set("has_table", /^\s*\|.*\|\s*$/m.test(input.text) || /<table[\s>]/i.test(input.text) ? 1 : 0);
  return PAGE_VERIFIER_FITTED.features.map((name) => values.get(name) ?? 0);
}

const sigmoid = (z: number): number => 1 / (1 + Math.exp(-z));

/** Calibrated P(fail) for a feature vector in the fitted order. */
export function pFailFromFeatures(x: readonly number[], fit = PAGE_VERIFIER_FITTED): number {
  let z = fit.intercept;
  for (let i = 0; i < fit.coef.length; i++) {
    z += (fit.coef[i]! * ((x[i] ?? 0) - fit.mean[i]!)) / fit.scale[i]!;
  }
  const raw = Math.min(Math.max(sigmoid(z), 1e-4), 1 - 1e-4);
  return sigmoid(fit.plattSlope * Math.log(raw / (1 - raw)) + fit.plattIntercept);
}

// ---- Gating -----------------------------------------------------------------

export interface VerifierGate {
  /** USD the operator pays for one unit (0..1) of page content quality; null disables the verifier. */
  valueUsdPerQualityUnit: number | null;
  /** Overrides of the fitted calibration-split constants (e.g. a different escalation target). */
  gainGivenFail?: number;
  escalationUsdPerPage?: number;
  minValueUsdPerQualityUnit?: number;
}

/** pFail at or above which escalation pays for itself, or null when the verifier should not run. */
export function escalationThreshold(gate: VerifierGate): number | null {
  const v = gate.valueUsdPerQualityUnit;
  const min = gate.minValueUsdPerQualityUnit ?? PAGE_VERIFIER_FITTED.minValueUsdPerQualityUnit;
  if (v === null || !Number.isFinite(v) || v <= 0 || v < min) return null;
  const gain = gate.gainGivenFail ?? PAGE_VERIFIER_FITTED.gainGivenFail;
  const cost = gate.escalationUsdPerPage ?? PAGE_VERIFIER_FITTED.escalationUsdPerPage;
  return Math.min(1, cost / (gain * v));
}

// ---- Models ------------------------------------------------------------------

const catalogModel = (id: string): DecisionModel => {
  const model = findDecisionModel(id);
  if (!model) throw new Error(`verifier decision model ${id} missing from the shared catalog`);
  return model;
};

/** Verifier members come from the shared decision-model catalog (one source of ids, prices and limits). */
export const VERIFIER_MODELS: Record<VerifierSlot, DecisionModel> = {
  omni: catalogModel("cloudflare/clef-omni"),
  flash: catalogModel("cloudflare/clef-flash"),
};

export interface VerifierMember {
  slot: VerifierSlot;
  model: DecisionModel;
  /** Client that records verifier usage. */
  client: DecisionClient;
}

// ---- Verifier -----------------------------------------------------------------

export interface DecisionVerifierOptions {
  members: Record<VerifierSlot, VerifierMember>;
  /** Client that records canary usage (metric page-route-decision-canary). */
  canaryClient: DecisionClient;
  gate: VerifierGate;
  health?: DecisionModelHealthRegistry;
  /** Loads the rendered page as PNG/JPEG bytes; defaults to reading `request.imagePath`. */
  loadImage?: (request: VerifierRequest) => Promise<Uint8Array | null>;
  documentId?: string;
  signal?: AbortSignal;
}

export interface VerifierTraceEntry {
  pageNumber: number;
  outcome: "verified" | "abstained";
  reason: string;
  pFail?: number;
}

export async function defaultVerifierLoadImage(request: VerifierRequest): Promise<Uint8Array | null> {
  if (!request.imagePath) return null;
  const bytes = await readFile(request.imagePath);
  return sharp(bytes)
    .resize({ width: VERIFIER_IMAGE_LONG_EDGE, height: VERIFIER_IMAGE_LONG_EDGE, fit: "inside", withoutEnlargement: true })
    .png()
    .toBuffer();
}

export class DecisionModelVerifier implements CascadeVerifier {
  /** Why each page was or was not verified, for run diagnostics. */
  readonly trace: VerifierTraceEntry[] = [];
  private readonly health: DecisionModelHealthRegistry;

  constructor(private readonly o: DecisionVerifierOptions) {
    this.health = o.health ?? decisionModelHealth;
  }

  private abstain(pageNumber: number, reason: string): null {
    this.trace.push({ pageNumber, outcome: "abstained", reason });
    return null;
  }

  async verify(request: VerifierRequest): Promise<VerifierVerdict | null> {
    const threshold = escalationThreshold(this.o.gate);
    if (threshold === null) return this.abstain(request.pageNumber, "value-of-quality-below-gate");
    if (request.text.trim() === "") return this.abstain(request.pageNumber, "empty-candidate");

    const image = await (this.o.loadImage ?? defaultVerifierLoadImage)(request);
    if (!image) return this.abstain(request.pageNumber, "no-page-image");

    const state = [imageDataUrlPart(image), CANDIDATE_LABEL + request.text.slice(0, VERIFIER_MAX_CANDIDATE_CHARS)];
    const slots = Object.keys(this.o.members) as VerifierSlot[];
    try {
      for (const slot of slots) {
        const { model } = this.o.members[slot];
        await this.health.ensureHealthy(model, () => runCanary(this.o.canaryClient, model, { signal: this.o.signal }));
      }
    } catch (error) {
      return this.abstain(request.pageNumber, error instanceof DecisionModelUnhealthyError ? `unhealthy:${error.modelId}` : `canary-error:${String(error).slice(0, 120)}`);
    }

    const results = await Promise.allSettled(
      slots.map((slot) => this.o.members[slot].client.ask(this.o.members[slot].model, state, VERIFIER_QUESTIONS, { signal: this.o.signal })),
    );
    const answers = {} as Record<VerifierSlot, Record<string, DecisionAnswer>>;
    let costUsd = 0;
    for (const [i, outcome] of results.entries()) {
      const slot = slots[i]!;
      const member = this.o.members[slot];
      if (outcome.status === "rejected") {
        if (this.o.signal?.aborted) throw outcome.reason;
        const reason = outcome.reason;
        if (!(reason instanceof DecisionUnavailableError) && (!(reason instanceof DecisionRequestError) || reason.status === null || reason.status >= 500)) {
          this.health.markUnhealthy(member.model.id, String(reason).slice(0, 200));
        }
        return this.abstain(request.pageNumber, `call-failed:${member.model.id}`);
      }
      const result: DecisionCallResult = outcome.value;
      costUsd += result.costCents / 100;
      const degenerate = detectDegenerate(answerSignals(result.answers));
      if (degenerate) {
        this.health.markUnhealthy(member.model.id, new DecisionDegenerateError(member.model.id, degenerate).message);
        return this.abstain(request.pageNumber, `degenerate:${member.model.id}`);
      }
      const missing = Object.keys(VERIFIER_QUESTIONS).filter((q) => !(q in result.answers));
      if (missing.length > 0) return this.abstain(request.pageNumber, `missing-answers:${member.model.id}`);
      answers[slot] = result.answers;
    }

    const pFail = pFailFromFeatures(verifierFeatures({ targetId: request.targetId, text: request.text, answers }));
    this.trace.push({ pageNumber: request.pageNumber, outcome: "verified", reason: `pFail>=${threshold.toFixed(3)}?`, pFail });
    return { pFail, escalate: pFail >= threshold, costUsd };
  }
}

// ---- Wiring ---------------------------------------------------------------------

export interface CreateVerifierOptions {
  ledger: PipelineUsageEventLedger;
  privacyMode: string | null | undefined;
  gate: VerifierGate;
  documentId?: string;
  env?: NodeJS.ProcessEnv;
  fetchImpl?: typeof fetch;
  health?: DecisionModelHealthRegistry;
  loadImage?: DecisionVerifierOptions["loadImage"];
  signal?: AbortSignal;
}

/**
 * Builds the verifier with usage recorded through the pipeline ledger: verifier calls under metric
 * `page-route-decision` (role `verify`), canaries under `page-route-decision-canary`.
 */
export function createDecisionVerifier(options: CreateVerifierOptions): DecisionModelVerifier {
  const client = createDecisionClient({
    privacyMode: options.privacyMode,
    ...(options.env ? { env: options.env } : {}),
    ...(options.fetchImpl ? { fetchImpl: options.fetchImpl } : {}),
    onUsage: (model, result) =>
      recordDecisionUsage(options.ledger, model, result, {
        ...(options.documentId ? { documentId: options.documentId } : {}),
        role: "verify",
        format: VERIFIER_FORMAT,
      }),
  });
  const canaryClient = createDecisionClient({
    privacyMode: options.privacyMode,
    ...(options.env ? { env: options.env } : {}),
    ...(options.fetchImpl ? { fetchImpl: options.fetchImpl } : {}),
    onUsage: (model, result) =>
      recordDecisionUsage(options.ledger, model, result, {
        ...(options.documentId ? { documentId: options.documentId } : {}),
        role: "canary",
        metric: PAGE_ROUTE_DECISION_CANARY_METRIC,
      }),
  });
  return new DecisionModelVerifier({
    members: {
      omni: { slot: "omni", model: VERIFIER_MODELS.omni, client },
      flash: { slot: "flash", model: VERIFIER_MODELS.flash, client },
    },
    canaryClient,
    gate: options.gate,
    ...(options.health ? { health: options.health } : {}),
    ...(options.loadImage ? { loadImage: options.loadImage } : {}),
    ...(options.documentId ? { documentId: options.documentId } : {}),
    ...(options.signal ? { signal: options.signal } : {}),
  });
}
